import java.io.*;
import java.util.*;

public class Check4 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] tokens = line.trim().split("\\s+");
        long n = Long.parseLong(tokens[0]);
        long m = Long.parseLong(tokens[1]);
        long result = process(n, m);
        System.out.println(result);
    }

    static long process(long n, long m) {
        long minVal = Math.min(n, m);
        long maxVal = Math.max(n, m);
        long totalCells = n * m;

        if (minVal <= 3 && maxVal <= 3) {
            if (minVal == 1 || maxVal == 1) return 0;
            if (minVal == 2 && maxVal == 2) return 0;
            if (minVal == 2 && maxVal == 3) return 4;
            if (minVal == 3 && maxVal == 2) return 4;
            if (minVal == 3 && maxVal == 3) return 8;
            return 0;
        }

        if (minVal == 1) {
            long modVal = maxVal % 6;
            if (modVal == 4) modVal = 2;
            else if (modVal == 5) modVal = 1;
            return totalCells - modVal;
        } else if (minVal == 2) {
            if (maxVal == 3 || maxVal == 7) maxVal = 2;
            else maxVal = 0;
            return totalCells - maxVal;
        } else {
            return totalCells - (totalCells % 2);
        }
    }
}
